<?php
declare(strict_types=1);
function renderMemberFinalization(array $p,?array $pending=null,string $error=''):void
{
    $s=$p['summary'];$preview=$pending!==null;
    ?><div class="match-review grouped-review"><a href="matches.php">← Identity review</a><header class="review-page-header"><div><span class="review-eyebrow">ADMINISTRATOR REVIEW</span><h1>Finalize People &amp; Members</h1><p>Approved identity decisions already allocate BMA people and source links. Reuse those identities; verify membership separately.</p></div></header>
    <?php if($error!==''): ?><div class="alert alert-warning" role="alert"><?= e($error) ?></div><?php endif; ?>
    <section class="group-stats"><?php foreach(['approved_groups_awaiting_finalization'=>'Approved groups awaiting membership review','people_to_create'=>'New people needed','people_to_reuse'=>'Approved people to reuse','members_to_create'=>'Verified member records to create','relationships_to_establish'=>'New relationships needed'] as $key=>$label): ?><div class="group-stat"><strong><?= e($s[$key]) ?></strong><span><?= e($label) ?></span></div><?php endforeach; ?></section>
    <div class="review-card group-preview"><h2 class="h5">Verified associations and remaining work</h2><p><?= e($s['approved_stripe_associations']) ?> approved Stripe customer links · <?= e($s['approved_signer_associations']) ?> signer links · <?= e($s['approved_student_associations']) ?> student links · <?= e($s['existing_verified_relationships']) ?> existing verified relationships.</p><p>New associations required: Stripe <?= e($s['stripe_associations_to_establish']) ?>, signer <?= e($s['signer_associations_to_establish']) ?>, student <?= e($s['student_associations_to_establish']) ?>. These links were already established by approval; missing or inconsistent approvals are excluded, not guessed.</p><p><?= e($s['membership_needs_review']) ?> students need membership verification · <?= e($s['participants_without_membership']) ?> verified participants have no established member record · <?= e($s['trial_or_waiver_only']) ?> have an explicit trial/waiver-only review · <?= e($s['records_still_requiring_review']) ?> unresolved/conflicting records excluded.</p><p>Profiles retain original account, subscription and waiver history. Shared-payer payments are not assigned to one child. No dates, programs or dues will be inferred.</p></div>
    <?php if($p['errors']!==[]): ?><div class="alert alert-warning"><ul><?php foreach($p['errors'] as $message): ?><li><?= e($message) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
    <?php if(!$preview): ?><form method="post"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="phase" value="preview"><?php endif; ?>
    <?php foreach($p['people'] as $id=>$person): ?><section class="review-card group-preview"><h2 class="h5"><?= e($person['name']) ?> <small><?= e($person['bma_person_id']) ?></small></h2><p>Verified roles: <?= e(implode(', ',array_keys($person['roles']))) ?>. <?= e(count($person['waivers'])) ?> waivers · <?= e(count($person['stripe_accounts'])) ?> Stripe accounts.</p><p>Membership: <?= e($person['existing_member']['member_status']??'Not established') ?> · start <?= e($person['existing_member']['member_since']??'Unknown') ?> · end <?= e($person['existing_member']['member_until']??'Unknown') ?>. Last review: <?= e($person['membership_review']['decision']['kind']??'Not reviewed') ?>.</p><?php if($person['existing_member']!==null): ?><a class="btn btn-outline-secondary" href="/member.php?<?= e(http_build_query(['id'=>$person['existing_member']['id']])) ?>">Member profile</a><?php endif; ?>
    <?php if($preview&&isset($p['changes'][$id])): $decision=$p['changes'][$id]; ?><div class="alert alert-info mt-3">Write: <?= e($decision['established']?($person['existing_member']===null?'Create member with status ':'Update reviewed status to '):'Record participation review only: ') ?><?= e($decision['kind']) ?><br>Evidence: <?= e($decision['evidence']) ?></div>
    <?php elseif(!$preview&&$person['eligible_student']): ?><div class="form-check my-3"><input class="form-check-input" type="checkbox" id="include-<?= e($id) ?>" name="people[<?= e($id) ?>][include]" value="1"><label class="form-check-label" for="include-<?= e($id) ?>">Review this student</label></div><label class="form-label" for="kind-<?= e($id) ?>">Verified outcome</label><select class="form-select" id="kind-<?= e($id) ?>" name="people[<?= e($id) ?>][kind]"><?php foreach(['undetermined'=>'Membership not yet determined','waiver_only'=>'Waiver participant only','trial_participant'=>'Trial attendance; membership not established','unknown'=>'Established member; current status unknown','active'=>'Established active member','inactive'=>'Established inactive member','former'=>'Established former member','trial'=>'Established trial enrollment'] as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select><div class="form-check my-3"><input class="form-check-input" type="checkbox" id="established-<?= e($id) ?>" name="people[<?= e($id) ?>][established]" value="1"><label class="form-check-label" for="established-<?= e($id) ?>">I separately verified an actual academy membership/enrollment relationship. A waiver or payer subscription alone is insufficient.</label></div><label class="form-label" for="evidence-<?= e($id) ?>">Membership or participation evidence / review reason</label><textarea class="form-control" id="evidence-<?= e($id) ?>" name="people[<?= e($id) ?>][evidence]" rows="2" maxlength="2000"></textarea><?php elseif(!$person['eligible_student']): ?><p class="text-secondary">Payer/signer only: no member record is proposed.</p><?php endif; ?></section><?php endforeach; ?>
    <?php if($p['people']===[]): ?><div class="alert alert-info">No consistent, manually approved identities are available. Resolve identity conflicts first; nothing has been created.</div><?php endif; ?>
    <?php if(!$preview): ?><label class="form-label" for="backup-reference">Production database backup reference (private location/time; required before production writes)</label><input class="form-control mb-3" name="backup_reference" id="backup-reference" maxlength="500"><button class="btn btn-primary">Preview Selected Finalization</button></form>
    <?php elseif($p['changes']!==[]&&$p['errors']===[]): ?><form method="post" class="group-confirm-form"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="operation_id" value="<?= e($pending['operation']) ?>"><input type="hidden" name="confirm_count" value="<?= e(count($p['changes'])) ?>"><p>Exactly <?= e(count($p['changes'])) ?> student reviews; <?= e($s['members_to_create']) ?> member inserts and <?= e($s['members_to_update']) ?> reviewed status updates. No people, source records, financial records, dates or relationship changes are included.</p><div class="form-check my-3"><input class="form-check-input" type="checkbox" name="acknowledge" value="1" id="final-ack" required><label class="form-check-label" for="final-ack">I reviewed the exact writes and confirm the required database backup is complete. Apply and audit this finalization.</label></div><button class="btn btn-primary">Confirm Reviewed Finalization</button></form><?php else: ?><div class="alert alert-info">No new writes are available. Nothing was changed.</div><?php endif; ?>
    <?php if($p['excluded']!==[]): ?><details class="mt-4"><summary>Excluded identity groups and records</summary><ul><?php foreach($p['excluded'] as $scope=>$reason): ?><li><?= e($scope) ?> · <?= e($reason) ?></li><?php endforeach; ?></ul></details><?php endif; ?></div><script src="/assets/js/group-match-review.js" defer></script><?php
}
